\begin{exercise}
\label{prob:lie-group-dimension-bound}
\dcref{ch5:5-12}

Suppose $M$ is a connected $n$-dimensional Riemannian manifold, and $G$ is a Lie group acting isometrically and effectively on $M$. Show that $\dim G \leq n(n+1)/2$. (Used on p.\ 261.)
\end{exercise}

